CREATE OR REPLACE FUNCTION calculate_sustainability_index(p_equip_code text)
RETURNS numeric AS $$
DECLARE
    v_energy_efficiency numeric;
    v_power_source text;
    v_multiplier numeric;
BEGIN
    -- Get energy efficiency from EquipmentType's type_indices
    SELECT et.type_indices->>'energy_efficiency_idx' INTO v_energy_efficiency
    FROM "Equipment" e
    JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
    WHERE e."EQUIP_CODE" = p_equip_code;

    -- Get power source from PowerBattery's battery_telemetry
    SELECT pb.battery_telemetry->'power_state'->>'primary_source' INTO v_power_source
    FROM "Equipment" e
    JOIN "PowerBattery" pb ON e."EQUIP_CODE" = pb.equip_ref
    WHERE e."EQUIP_CODE" = p_equip_code;

    -- Determine multiplier based on power source
    CASE
        WHEN v_power_source IN ('Solar', 'Wind', 'Hybrid') THEN v_multiplier := 1.5
        WHEN v_power_source = 'Battery' THEN v_multiplier := 1.0
        WHEN v_power_source = 'Diesel' THEN v_multiplier := 0.7
        ELSE v_multiplier := 0
    END;

    -- Calculate and return ESI
    RETURN ROUND(CAST(v_energy_efficiency * v_multiplier AS numeric), 2);
END;
$$ LANGUAGE plpgsql;

